        String str = "successes";
        int[] freq = new int[256];
        for (char ch : str.toCharArray())
            freq[ch]++;

        char minChar = str.charAt(0), maxChar = str.charAt(0);
        int min = Integer.MAX_VALUE, max = Integer.MIN_VALUE;

        for (char ch : str.toCharArray()) {
            if (freq[ch] < min && freq[ch] != 0) {
                min = freq[ch];
                minChar = ch;
            }
            if (freq[ch] > max) {
