        String[] words = str.split(" ");
        String small = "", big = "";
        for (String word : words) {
            if (isPalindrome(word)) {
                if (small.equals("") || word.length() < small.length()) small = word;
                if (big.equals("") || word.length() > big.length()) big = word;
            }
        }
        System.out.println("Smallest palindrome: " + small);
